"use client";

import Link from "next/link";
import Image from "next/image";

const money = (value) => `₹${Number(value || 0).toLocaleString("en-IN")}`;
const date = (value) => value ? new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "short", year: "numeric" }).format(new Date(value)) : "—";

export default function VendorProducts({ products, onAdd, onEdit, onDelete }) {
  return <section><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="marketplace-eyebrow">Catalog management</p><h2 className="mt-2 text-3xl font-bold">My Products</h2><p className="mt-2 text-sm text-slate-600">Manage the real listings attached to your supplier account.</p></div><button type="button" onClick={onAdd} className="marketplace-button-primary">Add product</button></div>
    {!products.length ? <div className="mt-7 rounded-2xl border border-dashed border-slate-300 bg-white px-5 py-14 text-center"><h3 className="text-lg font-bold">No products listed</h3><p className="mt-2 text-sm text-slate-600">Add your first catalog listing to appear in the marketplace.</p></div> : <div className="mt-7 grid gap-4">{products.map((product) => <article key={product.id} className="grid gap-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-[7rem_minmax(0,1fr)] sm:p-5 lg:grid-cols-[7rem_minmax(0,1fr)_auto] lg:items-center"><Image unoptimized width={240} height={240} src={product.images?.[0] || "/industrial.jpg"} alt="" className="aspect-square w-full rounded-xl bg-slate-100 object-cover"/><div className="min-w-0"><p className="text-xs font-bold uppercase tracking-wider text-orange-700">{product.category || "Uncategorized"}</p><h3 className="mt-1 break-words text-lg font-bold">{product.name}</h3><dl className="mt-3 grid grid-cols-2 gap-x-5 gap-y-2 text-sm sm:grid-cols-4"><div><dt className="text-xs text-slate-500">Base price</dt><dd className="font-bold">{money(product.basePrice)}</dd></div><div><dt className="text-xs text-slate-500">MOQ</dt><dd className="font-bold">{product.moq}</dd></div><div><dt className="text-xs text-slate-500">Stock</dt><dd className="font-bold">{product.stock}</dd></div><div><dt className="text-xs text-slate-500">Created</dt><dd className="font-bold">{date(product.createdAt)}</dd></div></dl></div><div className="flex flex-wrap gap-2 sm:col-start-2 lg:col-start-auto"><Link href={`/product/${product.id}`} className="min-h-10 rounded-lg border border-slate-300 px-3 py-2 text-sm font-bold hover:bg-slate-50">View</Link><button type="button" onClick={() => onEdit(product)} className="min-h-10 rounded-lg border border-orange-300 px-3 text-sm font-bold text-orange-800 hover:bg-orange-50">Edit</button><button type="button" onClick={() => onDelete(product)} className="min-h-10 rounded-lg border border-rose-200 px-3 text-sm font-bold text-rose-700 hover:bg-rose-50">Delete</button></div></article>)}</div>}
  </section>;
}
